<script setup lang="ts">
/**
 * The records screen (`design/archetypes/list-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { useTemplateRef } from 'vue'

import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/archetypes/list-page.module.css'
import EmptyState, { type EmptyStateProps } from '../structure/EmptyState.vue'
import Inline from '../layout/Inline.vue'
import PageHeader from '../structure/PageHeader.vue'

export interface ListPageProps {
  description?: string
  empty?: boolean
  /**
   * The empty state, required so the page always defines what it shows with no records.
   */
  emptyState: EmptyStateProps
  title: string
}

defineOptions({ name: 'ListPage', inheritAttrs: false })

const props = withDefaults(defineProps<ListPageProps>(), { empty: false })
defineSlots<{
  actions?: (props: Record<string, never>) => unknown
  default: (props: Record<string, never>) => unknown
  filters?: (props: Record<string, never>) => unknown
  summary?: (props: Record<string, never>) => unknown
}>()
const nothing = useTemplateRef<HTMLElement>('nothing')
const records = useTemplateRef<HTMLElement>('records')
const recordsPresent = usePresence(() => !props.empty, records, 'listpage.bodyswap')
const emptyPresent = usePresence(() => props.empty, nothing, 'listpage.bodyswap')
</script>

<template>
  <div :class="styles.page" :data-empty="empty ? '' : undefined" data-member="list-page">
    <PageHeader :title="title" :description="description">
      <template v-if="$slots.actions" #actions>
        <slot name="actions" />
      </template>
    </PageHeader>
    <slot name="summary" />
    <Inline v-if="$slots.filters" :gap="3" :wrap="true">
      <slot name="filters" />
    </Inline>
    <div :class="styles.bodySlot">
      <div v-if="recordsPresent" ref="records" :class="styles.body">
        <slot />
      </div>
      <div v-if="emptyPresent" ref="nothing" :class="styles.body">
        <EmptyState
          :icon="emptyState.icon"
          :title="emptyState.title"
          :description="emptyState.description"
        >
          <template v-if="emptyState.action !== undefined" #action>
            <component :is="emptyState.action" />
          </template>
          <template v-if="emptyState.secondaryAction !== undefined" #secondaryAction>
            <component :is="emptyState.secondaryAction" />
          </template>
        </EmptyState>
      </div>
    </div>
  </div>
</template>
